    for (int i = 0; i < n; i++) {
        cout << 'הזן איבר: ';
        cin >> arr[i];
        sum += arr[i];
    }
    cout << 'סכום האיברים: ' << sum;
    return 0;
}
```

1. טעות נפוצה במימוש מיון בועתי היא אי-שימוש במשתנה דגל (flag) כדי לבדוק אם היה שינוי במהלך האיטרציה; אם לא היה שינוי, ניתן לסיים את המיון מוקדם. 2. כאשר לא משתמשים בדגל, האלגוריתם עשוי להמשיך לרוץ גם כאשר המערך כבר ממויין, מה שגורם לבזבוז משאבים ומעלה את זמן הריצה ללא צורך. 3. במיון בועתי תקני, בכל איטרציה, יש לבצע השוואות בין זוגות סמוכים של איברים ולהחליף את מקומותיהם אם הם מסודרים בצורה לא נכונה. 4. כך, האלגוריתם מבצע מספר שלבים בכל פעם, והדגל מאפשר לו לגלות מתי לא נדרשות עוד החלפות. 5. לדוגמה, קוד מיון בועתי נכון עשוי להיראות כך: 
```cpp
void bubbleSort(int arr[], int n) {
    bool swapped;
    for (int i = 0; i < n-1; i++) {
        swapped = false;
        for (int j = 0; j < n-i-1; j++) {
            if (arr[j] > arr[j+1]) {
                std::swap(arr[j], arr[j+1]);
                swapped = true;
            }
        }
        if (!swapped) break;
    }
}
```

1. מחרוזות C-style strings הן מערכים של תווי תו, והן מסתיימות בתו מיוחד ('�') כדי לציין את סיום המחרוזת, בעוד שמחרוזות std::string הן אובייקטים שמספקים ממשק נוח יותר וניהול זיכרון אוטומטי. 2. כאשר עובדים עם C-style strings, יש צורך לנהל את הזיכרון באופן ידני, מה שמוביל לסיכונים כמו דליפות זיכרון או גישה לא חוקית בזיכרון. לדוגמה, קוד שמחשב את אורך המחרוזת עשוי להיראות כך: 
```c++
char str[] = "Hello";
int length = 0;
while (str[length] != '\0') { length++; }
```. 3. לעומת זאת, מחרוזות std::string מאפשרות שימוש בפונקציות מוכנות מראש כמו length() לחישוב אורך המחרוזת, והן מספקות יכולות נוספות כמו חיבור מחרוזות בצורה קלה: 
```c++
std::string str = "Hello";
int length = str.length();
```. 4. יתרון מרכזי של std::string הוא שהן מביאות עימוד אוטומטי של הזיכרון, מה שמפחית את הצורך לדאוג לניהול ידני של זיכרון. 5. החיסרון של std::string הוא שבמצבים של ביצועים קריטיים או במערכות עם משאבים מוגבלים, המימוש שלהן עלול להיות כבד יותר.

1. קטע הקוד משתמש במצביע רגיל להקצות זיכרון עבור משתנה מסוג int, אך לא משחרר את הזיכרון בסיום השימוש. 2. כאשר הקצאות זיכרון מתבצעות בעזרת new, יש צורך להשתמש ב-delete לשחרור הזיכרון לאחר השימוש, אחרת נתרחש זליגת זיכרון (memory leak). 3. כאשר משתמשים במצביע רגיל, הזיכרון שייך לתחום המוגדר (stack), והוא משתחרר אוטומטית בסיום הפונקציה, אך בעבודה עם new, יש צורך לנהל את השחרור בעצמנו. 4. ניהול לא נכון של זיכרון דינאמי עלול להוביל לבעיות כגון חוסר גישה לזיכרון שהוקצה או שימוש בזיכרון משוחרר (dangling pointer). 5. לדוגמה, אם נשתמש בקוד הבא: 
```cpp
int* ptr = new int(5);
cout << *ptr;
delete ptr;
```
כאן, הקצינו זיכרון לדינמי ונדרש לשחרר אותו כדי להימנע מבעיות ניהול זיכרון.

1. תנאים מקוננים (if/else) מאפשרים לבצע בדיקות מורכבות יותר על מספר מצבים שונים, טכניקת דיבוב של תנאים בתוך תנאים יכולה להקל על צפייה בניהול תנאים מרובים. 2. לדוגמה, קטע קוד עם תנאים מקוננים עשוי לבדוק האם מספר הוא חיובי, ואם כן, לבדוק אם הוא זוגי: 
```cpp
if (num > 0) {
    if (num % 2 == 0) {
        // מספר חיובי וזוגי
    }
}
``` 3. לעומת זאת, שימוש בתנאים פשוטים (if) ניתן להציג בצורה ברור יותר כאשר יש צורך לבצע פעולה בודדת כשמתקיים תנאי: 
```cpp
if (num > 0) {
    // מספר חיובי
}
``` 4. השימוש בתנאים פשוטים מאפשר קוד פחות מסודר במקרים שחייבים רק פעולה אחת, אך יכול להחמיר אם נדרשות בדיקות רבות. 5. בסיטואציות עם מספר תנאים המערבות אופרציות שונות, התנאים המקוננים יהיו עדיפים כדי לשמור על מבנה לוגי ברור.

1. אלגוריתם מיון מהיר פועל על ידי חלוקת הבעיה לתת-בעיות, כאשר הוא בוחר 'פיבוט' וממיין את המערך כך שכל האיברים הקטנים ממנו נמצאים משמאל והאיברים הגדולים ממנו מימין. 2. ביצוע ההשוואות וההחלפות במקרה הגרוע יכול להוביל למורכבות זמן של O(n^2), במיוחד אם המערך כבר מיון או אם הפיבוט נבחר לא נכון, אך במקרה הממוצע מורכבות הזמן היא O(n log n). 3. במנוגד לכך, מיון בועות מתנהל באופן סדרתי על המערך, והשוואת זוגות סמוכים גורמת לו להיות פחות יעיל, עם מורכבות של O(n^2) גם במקרה הממוצע. 4. חשוב להבין את ההשפעה של בחירת הפיבוט על הביצועים: פיבוט טוב יכול לשפר מאוד את המהירות, בעוד פיבוט גרוע יפגע בביצועים. 5. לדוגמה, בקוד הבא ניתן לראות את עקרונות המיון המהיר: 
```cpp
void quickSort(int arr[], int low, int high) {
  if (low < high) {
    int pivot = partition(arr, low, high);
    quickSort(arr, low, pivot - 1);
    quickSort(arr, pivot + 1, high);
  }
}
```

1. מערכים של תו אחד (C-style strings) הם פשוטים ומאפשרים גישה ישירה לכתובת הזיכרון של המחרוזת, אך הם דורשים ניהול ידני של זיכרון ויש לבקש את גודל המחרוזת באופן ידני. 2. לעומת זאת, std::string מספקת ניהול אוטומטי של זיכרון, ומאפשרת שימוש במגוון פונקציות מועילות כמו append, substr ו-find. 3. דוגמה לשימוש במערך תו אחד: 
```cpp
char str1[] = "Hello";
``` 4. דוגמה לשימוש ב-std::string: 
```cpp
std::string str2 = "Hello";
str2 += " World!";
``` 5. חסרון במערכים של תו אחד הוא שהם אינם תומכים בשינויים דינמיים בקלות כמו std::string, שהיא גמישה וידידותית יותר למשתמש.

1. קטע הקוד המוצג יחשב את סכום כל האיברים במערך, אך יש לוודא שהמחשב מגדיר את המערך עם גודל נכון כדי למנוע גישה מחוץ לגבולות המערך. 2. יש לבדוק אם המערך מושלם, כלומר אם הוא מכיל לפחות איבר אחד לפני שמבצעים חישוב סכום, כדי למנוע חישוב לא מדויק. 3. דוגמה לקוד היא: 
```cpp
int arr[5] = {1, 2, 3, 4, 5};
int sum = 0;
for (int i = 0; i < 5; ++i) {
    sum += arr[i];
}
```. 4. בעיה פוטנציאלית נוספת היא שלא לכלול הגדרה של גודל המערך כקבוע או כמשתנה, מה שעלול להוביל לטעויות בתכנות, אם יש צורך לשנות גודל. 5. במקרה שהמערך לא מאותחל בצורה תקינה, החישוב עלול להחזיר ערכים לא צפויים.

1. הקוד המוצג מבצע המרה של מספר שלם בבסיס עשר למספר בבסיס בינארי באמצעות חלוקה ברציפות ב-2 עד שהמספר מתאפס. 2. כל פעם שהשארית מהחלוקה נשמרת, היא מציינת את ספרת הבינארי הנוכחית, ולכן סדר ההוספה של השאריות חשוב. 3. שגיאה פוטנציאלית היא אם המשתמש יזין מספר שלילי, כי המרה של מספרים שליליים לבינארי אינה נתמכת בדרך כלל בשיטה זו. 4. דוגמה לקוד עשויה להיות: 
```cpp
#include <iostream>
using namespace std;

int main() {
    int num;
    cout << "הכנס מספר: ";
    cin >> num;
    if(num < 0) {
        cout << "מספר שלילי אינו ניתן להמרה.
";
    } else {
        string binary = "";
        while(num > 0) {
            binary = to_string(num % 2) + binary;
            num /= 2;
        }
        cout << "המספר בבסיס בינארי הוא: " << binary;
    }
    return 0;
}
```

1. במקרים מסוימים, השוואה בין ערכים יכולה לגרום לתוצאה לא צפויה כאשר אחד מהערכים הוא NULL או לא מאותחל. 2. כאשר יש מבנה if/else מקונן, חשוב לדאוג שהשוואות מתבצעות על ערכים תקינים כדי למנוע חריגות. 3. למשל, אם קוד בודק אם משתנה x הוא חיובי ולאחר מכן בודק אם x גדול מ-10, אם x לא מאותחל, נקבל תוצאה שגויה. 4. לדוגמה, הקוד הבא לא ידפיס דבר אם x הוא NULL: 
```cpp
int x;
if (x > 0) {
    if (x > 10) {
        cout << 'x גדול מ-10';
    }
}
```. 5. תרחישים כאלו מדגישים את הצורך לבצע אתחול למשתנים לפני השימוש בהם כדי להבטיח שהלוגיקה עובדת כראוי.

